import {
  REVIEW_CALLS,
  REVIEWED,
  SAVED,
} from "@/lib/mockups/review-tracking-data"

function toggleIn(list: string[], id: string) {
  return list.includes(id) ? list.filter((item) => item !== id) : [...list, id]
}

/* ------------------------------------------------------------ review mode */

/**
 * Vansh's answer to "a checkbox on every row all the time is noise": the
 * page stays as it is, and a Review switch in the search row turns the
 * reviewing tools on — a checkbox column, a bookmark column, how many are
 * done, Mark all as reviewed, and two chips to narrow the list. Off, they
 * all go; what was ticked stays ticked for next time.
 */
export function ReviewModeIdea() {
  const [on, setOn] = React.useState(true)
  const [reviewed, setReviewed] = React.useState<string[]>(REVIEWED)
  const [saved, setSaved] = React.useState<string[]>(SAVED)
  const [notReviewed, setNotReviewed] = React.useState(false)
  const [savedOnly, setSavedOnly] = React.useState(false)
  const [open, setOpen] = React.useState<CallRow | null>(null)

  function markAll(rows: CallRow[]) {
    const before = reviewed
    setReviewed(
      Array.from(new Set([...reviewed, ...rows.map((row) => row.id)])),
    )
    toast(
      `${rows.filter((row) => !before.includes(row.id)).length} calls marked as reviewed`,
      {
        action: { label: "Undo", onClick: () => setReviewed(before) },
      },
    )
  }

  return (
    <ConversationsFrame
      above={
        on
          ? (rows: CallRow[]) => {
              const done = rows.filter((row) =>
                reviewed.includes(row.id),
              ).length
              return (
                <div className="flex items-center justify-between gap-4">
                  <span className="text-sm text-muted-foreground tabular-nums">
                    {done} of {rows.length} reviewed
                  </span>
                  {done < rows.length ? (
                    <Button
                      onClick={() => markAll(rows)}
                      size="sm"
                      variant="outline"
                    >
                      Mark all as reviewed
                    </Button>
                  ) : null}
                </div>
              )
            }
          : null
      }
      calls={REVIEW_CALLS}
      extraActive={on ? [notReviewed, savedOnly].filter(Boolean).length : 0}
      filterExtras={
        on ? (
          <>
            <ToggleFilter
              field="Not reviewed"
              onChange={setNotReviewed}
              value={notReviewed}
            />
            <ToggleFilter
              field="Saved"
              onChange={setSavedOnly}
              value={savedOnly}
            />
          </>
        ) : null
      }
      narrow={(rows) =>
        on
          ? rows.filter(
              (call) =>
                (!notReviewed || !reviewed.includes(call.id)) &&
                (!savedOnly || saved.includes(call.id)),
            )
          : rows
      }
      onClearExtras={() => {
        setNotReviewed(false)
        setSavedOnly(false)
      }}
      searchExtras={
        <Toggle
          onPressedChange={(pressed) => {
            setOn(pressed)
            if (!pressed) {
              setNotReviewed(false)
              setSavedOnly(false)
            }
          }}
          pressed={on}
          variant="outline"
        >
          <ReviewModeIcon />
          Review
        </Toggle>
      }
    >
      {(rows) => (
        <>
          <ReviewTable
            after={on ? [savedColumn(saved, setSaved)] : []}
            before={on ? [reviewedColumn(reviewed, setReviewed)] : []}
            calls={rows}
            onOpen={setOpen}
          />
          <CallDrawer
            actions={
              on && open ? (
                <>
                  <SaveButton
                    onToggle={() => setSaved((list) => toggleIn(list, open.id))}
                    saved={saved.includes(open.id)}
                  />
                  <ReviewedButton
                    onToggle={() =>
                      setReviewed((list) => toggleIn(list, open.id))
                    }
                    reviewed={reviewed.includes(open.id)}
                  />
                </>
              ) : null
            }
            call={open}
            calls={rows}
            onClose={() => setOpen(null)}
            onStep={setOpen}
          />
        </>
      )}
    </ConversationsFrame>
  )
}

/* --------------------------------------------------------- review session */

type Session = { ids: string[]; done: string[] }

/**
 * Mohammed's review session: filter the page down to what you mean to
 * review, then Start review. The drawer opens on the first call and walks
 * the filtered list; Mark reviewed and next ticks one and moves on, and the
 * drawer says how far through you are.
 *
 * Close the drawer and the session waits above the list, with Continue and
 * End review. Done-ness belongs to the session, not the call — Mohammed's
 * worry about one call turning up in two reviews: a call ticked in
 * yesterday's session starts unticked in today's.
 */
export function SessionIdea() {
  const [session, setSession] = React.useState<Session | null>(null)
  const [open, setOpen] = React.useState<CallRow | null>(null)

  const queue = session
    ? session.ids.flatMap((id) => REVIEW_CALLS.filter((call) => call.id === id))
    : []
  const nextUp = session
    ? (queue.find((call) => !session.done.includes(call.id)) ?? null)
    : null

  function start(rows: CallRow[]) {
    setSession({ ids: rows.map((row) => row.id), done: [] })
    setOpen(rows[0])
  }

  function end(current: Session) {
    setSession(null)
    setOpen(null)
    toast("Review ended", {
      description: `${current.done.length} of ${current.ids.length} calls reviewed.`,
      action: { label: "Undo", onClick: () => setSession(current) },
    })
  }

  function advance(call: CallRow) {
    if (!session) return
    const done = session.done.includes(call.id)
      ? session.done
      : [...session.done, call.id]
    const updated = { ...session, done }
    const index = queue.findIndex((item) => item.id === call.id)
    const following =
      queue.slice(index + 1).find((item) => !done.includes(item.id)) ??
      queue.find((item) => !done.includes(item.id))
    if (!following) {
      setSession(null)
      setOpen(null)
      toast.success("Review finished", {
        description: `${done.length} of ${updated.ids.length} calls reviewed.`,
      })
      return
    }
    setSession(updated)
    setOpen(following)
  }

  return (
    <ConversationsFrame
      above={
        session && !open ? (
          <Alert>
            <AlertTitle>Review in progress</AlertTitle>
            <AlertDescription className="tabular-nums">
              {session.done.length} of {session.ids.length} reviewed
            </AlertDescription>
            <AlertAction className="flex gap-2">
              <Button onClick={() => end(session)} size="sm" variant="outline">
                End review
              </Button>
              <Button onClick={() => setOpen(nextUp)} size="sm">
                Continue
              </Button>
            </AlertAction>
          </Alert>
        ) : null
      }
      calls={REVIEW_CALLS}
      narrow={(rows) => (session ? queue : rows)}
      searchExtras={(rows: CallRow[]) =>
        !session && rows.length > 0 ? (
          <Button onClick={() => start(rows)}>
            <StartReviewIcon />
            Start review
          </Button>
        ) : null
      }
    >
      {(rows) => (
        <>
          <ReviewTable
            calls={rows}
            onOpen={setOpen}
            selected={session ? nextUp?.id : null}
            timeMark={
              session
                ? (call) =>
                    session.done.includes(call.id) ? (
                      <span className="flex">
                        <MarkReviewedIcon className="size-3.5 text-success" />
                        <span className="sr-only">Reviewed</span>
                      </span>
                    ) : null
                : undefined
            }
          />
          <CallDrawer
            actions={
              session && open ? (
                <SessionButton
                  done={session.done.includes(open.id)}
                  last={
                    queue.filter(
                      (call) =>
                        call.id !== open.id && !session.done.includes(call.id),
                    ).length === 0
                  }
                  onClick={() => advance(open)}
                />
              ) : null
            }
            call={open}
            calls={rows}
            description={
              session && open
                ? `Reviewing ${queue.findIndex((call) => call.id === open.id) + 1} of ${queue.length} · ${session.done.length} done`
                : undefined
            }
            onClose={() => setOpen(null)}
            onStep={setOpen}
          />
        </>
      )}
    </ConversationsFrame>
  )
}

function SessionButton({
  done,
  last,
  onClick,
}: {
  done: boolean
  last: boolean
  onClick: () => void
}) {
  return (
    <Button onClick={onClick}>
      {done
        ? last
          ? "Finish"
          : "Next"
        : last
          ? "Mark reviewed and finish"
          : "Mark reviewed and next"}
    </Button>
  )
}

"use client"

import * as React from "react"

import {
  Table,
  TableBody,
  TableCell,
  TableHead,
  TableHeader,
  TableRow,
} from "@/components/ui/table"
import { DataTableHeaderRow } from "@/components/shared/data-table"
import {
  DirectionChip,
  OutcomeBadge,
  ScenarioChip,
  StatusBadge,
} from "@/components/mockups/conversations-revamp/list/status-badges"
import type { CallRow } from "@/lib/mockups/conversations-revamp-list-data"
import { cn } from "@/lib/utils"

/** A column an idea adds: its header and what each row shows in it. */
export type ExtraColumn = {
  id: string
  head: React.ReactNode
  cell: (call: CallRow, index: number) => React.ReactNode
  /** Narrow columns hug their content. */
  className?: string
}

/**
 * The Conversations table as it ships — Time, Direction, Phone number,
 * Scenario, Call status, Outcome, Duration — with the slots each idea needs:
 * columns before and after, a mark beside the time, and a selected row.
 *
 * A click anywhere on a row opens the call, as on the platform. Controls
 * inside a row (a checkbox, a bookmark) stop the click, so ticking a call
 * does not also open it.
 */
export function ReviewTable({
  calls,
  onOpen,
  before = [],
  after = [],
  selected,
  timeMark,
  timeStrong,
}: {
  calls: CallRow[]
  onOpen: (call: CallRow) => void
  before?: ExtraColumn[]
  after?: ExtraColumn[]
  /** The row drawn selected — the last call opened. The lilac the sidebar
   *  gives the page you are on, because muted is already the hover. */
  selected?: string | null
  /** A mark before the time, such as the unread dot. */
  timeMark?: (call: CallRow) => React.ReactNode
  /** Whether a row's time reads in full strength, as an unread email does. */
  timeStrong?: (call: CallRow) => boolean
}) {
  return (
    <Table>
      <TableHeader>
        <DataTableHeaderRow>
          {before.map((column) => (
            <TableHead
              className={cn("font-semibold text-foreground", column.className)}
              key={column.id}
            >
              {column.head}
            </TableHead>
          ))}
          {[
            "Time",
            "Direction",
            "Phone number",
            "Scenario",
            "Call status",
            "Outcome",
            "Duration",
          ].map((label) => (
            <TableHead className="font-semibold text-foreground" key={label}>
              {label}
            </TableHead>
          ))}
          {after.map((column) => (
            <TableHead
              className={cn("font-semibold text-foreground", column.className)}
              key={column.id}
            >
              {column.head}
            </TableHead>
          ))}
        </DataTableHeaderRow>
      </TableHeader>

      <TableBody>
        {calls.map((call, index) => (
          <TableRow
            className="cursor-pointer transition-colors duration-150 ease-out-cubic hover:bg-muted/50 motion-reduce:transition-none data-[state=selected]:bg-primary-tint data-[state=selected]:hover:bg-primary-tint"
            data-state={call.id === selected ? "selected" : undefined}
            key={call.id}
            onClick={(event) => {
              if (
                event.target instanceof Element &&
                event.target.closest("button, [role='checkbox']")
              ) {
                return
              }
              onOpen(call)
            }}
          >
            {before.map((column) => (
              <TableCell className={column.className} key={column.id}>
                {column.cell(call, index)}
              </TableCell>
            ))}
            <TableCell>
              <span
                className={cn(
                  "flex items-center gap-2 text-sm",
                  timeStrong?.(call)
                    ? "font-semibold text-foreground"
                    : "text-muted-foreground",
                )}
              >
                {timeMark ? (
                  <span className="flex w-2 shrink-0 justify-center">
                    {timeMark(call)}
                  </span>
                ) : null}
                {call.createdAt}
              </span>
            </TableCell>
            <TableCell>
              {call.direction ? (
                <DirectionChip direction={call.direction} />
              ) : (
                <span className="text-muted-foreground">—</span>
              )}
            </TableCell>
            <TableCell className="text-sm font-medium">
              {call.phoneNumber ?? (
                <span className="text-muted-foreground">—</span>
              )}
            </TableCell>
            <TableCell>
              <ScenarioChip scenario={call.scenario} />
            </TableCell>
            <TableCell>
              <StatusBadge
                scheduleOrigin={call.scheduleOrigin}
                status={call.status}
              />
            </TableCell>
            <TableCell>
              <OutcomeBadge status={call.outcome} />
            </TableCell>
            <TableCell className="text-sm font-medium tabular-nums">
              {call.duration}
            </TableCell>
            {after.map((column) => (
              <TableCell className={column.className} key={column.id}>
                {column.cell(call, index)}
              </TableCell>
            ))}
          </TableRow>
        ))}
      </TableBody>
    </Table>
  )
}

import * as React from "react"

import { Table, TableHead, TableRow } from "@/components/ui/table"
import { cn } from "@/lib/utils"

/**
 * The table shape the platform-consistency pass settled on, taken verbatim
 * from the product's `vnagar/platform-consistency` branch (then `sarj-ai/bulbul`,
 * now `sarj-ai/platform`):
 *
 *  - a bordered, radiused container with no padding of its own, so the header
 *    band reaches the edge instead of floating inside an inset;
 *  - a shaded header row that stays shaded on hover, so the band reads as
 *    chrome rather than a row you can click;
 *  - header labels at full-strength foreground and semibold, not muted;
 *  - a fixed 40px row on 16px cell padding, so rows do not grow with their
 *    content and the header lines up with the body.
 *
 * On that branch only `call-activity-table.tsx` had been brought across — the
 * trunk assignments and provisioned tables were still on plain `<TableHead>`
 * inside a `rounded-md border`. All three use it here.
 */
export function DataTable({
  className,
  children,
}: {
  className?: string
  children: React.ReactNode
}) {
  return (
    <div className="overflow-hidden rounded-lg border">
      <Table className={cn("[&_td]:h-10 [&_td]:px-4 [&_th]:px-4", className)}>
        {children}
      </Table>
    </div>
  )
}

export function DataTableHeaderRow({
  children,
}: {
  children: React.ReactNode
}) {
  return (
    <TableRow className="bg-muted/50 hover:bg-muted/50">{children}</TableRow>
  )
}

export function DataTableHead({
  className,
  children,
}: {
  className?: string
  children: React.ReactNode
}) {
  return (
    <TableHead className={cn("font-semibold text-foreground", className)}>
      {children}
    </TableHead>
  )
}

"use client"

import * as React from "react"
import { Cancel01Icon, PlusSignIcon } from "@hugeicons/core-free-icons"
import type { DateRange } from "react-day-picker"

import { Button } from "@/components/ui/button"
import { ButtonGroup } from "@/components/ui/button-group"
import { Calendar } from "@/components/ui/calendar"
import {
  Command,
  CommandEmpty,
  CommandGroup,
  CommandInput,
  CommandItem,
  CommandList,
} from "@/components/ui/command"
import {
  DropdownMenu,
  DropdownMenuCheckboxItem,
  DropdownMenuContent,
  DropdownMenuItem,
  DropdownMenuSeparator,
  DropdownMenuTrigger,
} from "@/components/ui/dropdown-menu"
import { Field, FieldLabel } from "@/components/ui/field"
import {
  InputGroup,
  InputGroupAddon,
  InputGroupInput,
  InputGroupText,
} from "@/components/ui/input-group"
import {
  Popover,
  PopoverContent,
  PopoverTrigger,
} from "@/components/ui/popover"
import { Separator } from "@/components/ui/separator"
import { icon } from "@/components/shared/icon"

const AddIcon = icon(PlusSignIcon, "AddIcon")
const ClearIcon = icon(Cancel01Icon, "ClearIcon")

export type { DateRange }
export type FilterOption = { value: string; label: string }
export type Range = { min?: number; max?: number }

/**
 * Filters as a row of chips under the search.
 *
 * A filter that is not set is one small chip naming its field — "+ Language" —
 * so ten of them cost a line, not a toolbar. Opening one gives its control the
 * room it needs (a checklist, a calendar) in a popover. Once set, the chip
 * reads its value and grows an × to clear it. Past two set filters the row
 * ends in Clear all.
 *
 * Show the three or four filters people reach for as chips; put the rest
 * behind AddFilter, which turns a chosen field into a chip of its own.
 */
export function FilterBar({
  children,
  activeCount = 0,
  onClearAll,
}: {
  children: React.ReactNode
  /** How many filters are set. Clear all appears at two. */
  activeCount?: number
  onClearAll?: () => void
}) {
  return (
    <div className="flex flex-wrap items-center gap-2">
      {children}
      {activeCount >= 2 ? (
        <Button variant="ghost" size="xs" onClick={onClearAll}>
          Clear all
        </Button>
      ) : null}
    </div>
  )
}

/**
 * The chip itself: "+ Field" when empty, "Field: value" and an × once set.
 * One tree for both states: swapping the button for a group once a value is
 * set would remount the trigger, and the open list would close on the first
 * tick.
 */
function Chip({
  field,
  summary,
  onClear,
  trigger,
}: {
  field: string
  /** What the filter is set to, or null when it is not set. */
  summary: string | null
  onClear: () => void
  trigger: (button: React.ReactElement) => React.ReactNode
}) {
  return (
    <ButtonGroup>
      {trigger(
        <Button variant="outline" size="xs">
          {summary ? (
            <>
              {field}: <span className="font-semibold">{summary}</span>
            </>
          ) : (
            <>
              <AddIcon />
              {field}
            </>
          )}
        </Button>,
      )}
      {summary ? (
        <Button
          variant="outline"
          size="icon-xs"
          aria-label={`Clear ${field}`}
          onClick={onClear}
        >
          <ClearIcon />
        </Button>
      ) : null}
    </ButtonGroup>
  )
}

/* ---------------------------------------------------------------- summaries */

/**
 * What a many-value filter reads once set: the value, two values when both
 * fit, and past that the first value and how many more — "Completed +2".
 * A bare count ("Status: 3") makes you open the chip to learn anything.
 */
function manySummary(options: FilterOption[], value: string[]) {
  if (!value.length) return null
  const labels = value.map(
    (item) => options.find((option) => option.value === item)?.label ?? item,
  )
  if (labels.length === 1) return labels[0]
  if (labels.length === 2 && labels.join(", ").length <= 24)
    return labels.join(", ")
  return `${labels[0]} +${labels.length - 1}`
}

const DAY = 24 * 60 * 60 * 1000

function datePresets(today: Date) {
  return [
    { label: "Today", from: today },
    { label: "Last 7 days", from: new Date(today.getTime() - 6 * DAY) },
    { label: "Last 30 days", from: new Date(today.getTime() - 29 * DAY) },
  ]
}

function dateSummary(value: DateRange | undefined, today: Date) {
  if (!value?.from) return null
  const preset = datePresets(today).find(
    (entry) =>
      value.from?.toDateString() === entry.from.toDateString() &&
      value.to?.toDateString() === today.toDateString(),
  )
  return (
    preset?.label ??
    [value.from, value.to]
      .filter(Boolean)
      .map((date) =>
        date!.toLocaleDateString("en-GB", { day: "numeric", month: "short" }),
      )
      .join(" – ")
  )
}

function rangeSummary(range: Range | null, unit: string) {
  if (!range) return null
  const { min, max } = range
  if (min !== undefined && max !== undefined) return `${min}–${max} ${unit}`
  if (min !== undefined) return `Over ${min} ${unit}`
  if (max !== undefined) return `Under ${max} ${unit}`
  return null
}

/** Past this many options the list gets a search box. */
const SEARCH_FROM = 8

/**
 * The one list every select filter opens, many-value or one-value, so the two
 * cannot drift apart: same rows, the tick on the right. A short list is the
 * standard dropdown menu, so it looks like every other dropdown in the
 * product; a long one needs a search box, so it is a command list. A set
 * many-value list ends in Clear.
 */
function OptionList({
  button,
  field,
  options,
  selected,
  onSelect,
  onClear,
  closeOnSelect,
}: {
  button: React.ReactElement
  field: string
  options: FilterOption[]
  selected: string[]
  onSelect: (value: string) => void
  onClear?: () => void
  /** One-value filters close on a pick; many-value ones stay open. */
  closeOnSelect: boolean
}) {
  const [open, setOpen] = React.useState(false)
  /* Ticked ones float to the top of a long list, so they are never scrolled
     out of sight — but only when it opens, not under the pointer. */
  const [order, setOrder] = React.useState(options)

  if (options.length < SEARCH_FROM) {
    return (
      <DropdownMenu modal={false} open={open} onOpenChange={setOpen}>
        <DropdownMenuTrigger asChild>{button}</DropdownMenuTrigger>
        <DropdownMenuContent
          align="start"
          className="w-auto min-w-(--radix-dropdown-menu-trigger-width)"
        >
          {options.map((option) => (
            <DropdownMenuCheckboxItem
              checked={selected.includes(option.value)}
              key={option.value}
              onSelect={(event) => {
                /* A many-value list stays open while ticking. */
                if (!closeOnSelect) event.preventDefault()
                onSelect(option.value)
              }}
            >
              {option.label}
            </DropdownMenuCheckboxItem>
          ))}
          {onClear && selected.length ? (
            <>
              <DropdownMenuSeparator />
              <DropdownMenuItem onSelect={onClear}>Clear</DropdownMenuItem>
            </>
          ) : null}
        </DropdownMenuContent>
      </DropdownMenu>
    )
  }

  return (
    <Popover
      open={open}
      onOpenChange={(next) => {
        if (next && options.length >= SEARCH_FROM)
          setOrder([
            ...options.filter((o) => selected.includes(o.value)),
            ...options.filter((o) => !selected.includes(o.value)),
          ])
        setOpen(next)
      }}
    >
      <PopoverTrigger asChild>{button}</PopoverTrigger>
      <PopoverContent align="start" className="w-64 p-0">
        <Command>
          {options.length >= SEARCH_FROM ? (
            <CommandInput placeholder={`Search ${field.toLowerCase()}`} />
          ) : null}
          <CommandList>
            <CommandEmpty>No match</CommandEmpty>
            <CommandGroup>
              {(options.length >= SEARCH_FROM ? order : options).map(
                (option) => (
                  <CommandItem
                    className="truncate"
                    data-checked={selected.includes(option.value)}
                    key={option.value}
                    onSelect={() => {
                      onSelect(option.value)
                      if (closeOnSelect) setOpen(false)
                    }}
                    value={option.label}
                  >
                    {option.label}
                  </CommandItem>
                ),
              )}
            </CommandGroup>
          </CommandList>
          {onClear && selected.length ? (
            <div className="border-t p-1">
              <Button
                className="w-full"
                onClick={onClear}
                size="sm"
                variant="ghost"
              >
                Clear
              </Button>
            </div>
          ) : null}
        </Command>
      </PopoverContent>
    </Popover>
  )
}

/** Pick one or more values. The list stays open while ticking. */
export function SelectFilter({
  field,
  options,
  value,
  onChange,
}: {
  field: string
  options: FilterOption[]
  value: string[]
  onChange: (value: string[]) => void
}) {
  return (
    <Chip
      field={field}
      summary={manySummary(options, value)}
      onClear={() => onChange([])}
      trigger={(button) => (
        <OptionList
          button={button}
          closeOnSelect={false}
          field={field}
          onClear={() => onChange([])}
          onSelect={(item) =>
            onChange(
              value.includes(item)
                ? value.filter((entry) => entry !== item)
                : [...value, item],
            )
          }
          options={options}
          selected={value}
        />
      )}
    />
  )
}

/** Pick exactly one value — a direction, a channel. Choosing closes it. */
export function ChoiceFilter({
  field,
  options,
  value,
  onChange,
}: {
  field: string
  options: FilterOption[]
  value: string | null
  onChange: (value: string | null) => void
}) {
  return (
    <Chip
      field={field}
      summary={options.find((option) => option.value === value)?.label ?? null}
      onClear={() => onChange(null)}
      trigger={(button) => (
        <OptionList
          button={button}
          closeOnSelect
          field={field}
          onSelect={(item) => onChange(item === value ? null : item)}
          options={options}
          selected={value ? [value] : []}
        />
      )}
    />
  )
}

/** A date range: presets first, then any range on the calendar. */
export function DateFilter({
  field,
  value,
  onChange,
  today,
}: {
  field: string
  value: DateRange | undefined
  onChange: (value: DateRange | undefined) => void
  /** What "today" is. Mock data is dated, so the demo fixes it. */
  today: Date
}) {
  return (
    <Chip
      field={field}
      summary={dateSummary(value, today)}
      onClear={() => onChange(undefined)}
      trigger={(button) => (
        <Popover>
          <PopoverTrigger asChild>{button}</PopoverTrigger>
          <PopoverContent align="start" className="w-auto">
            <div className="flex gap-2">
              <div className="flex flex-col gap-1">
                {datePresets(today).map((entry) => (
                  <Button
                    key={entry.label}
                    variant={
                      dateSummary(value, today) === entry.label
                        ? "secondary"
                        : "ghost"
                    }
                    size="sm"
                    className="justify-start"
                    onClick={() => onChange({ from: entry.from, to: today })}
                  >
                    {entry.label}
                  </Button>
                ))}
              </div>
              <Separator orientation="vertical" />
              <Calendar
                mode="range"
                selected={value}
                onSelect={onChange}
                defaultMonth={value?.from ?? today}
                disabled={{ after: today }}
              />
            </div>
          </PopoverContent>
        </Popover>
      )}
    />
  )
}

/**
 * A number between two bounds — duration, cost. The common bands are one
 * click; Min and Max take anything else, and either may be left empty.
 */
export function RangeFilter({
  field,
  unit,
  presets,
  value,
  onChange,
}: {
  field: string
  unit: string
  presets: Range[]
  value: Range | null
  onChange: (value: Range | null) => void
}) {
  const id = React.useId()
  const set = (next: Range) =>
    onChange(next.min === undefined && next.max === undefined ? null : next)
  const read = (raw: string) => (raw === "" ? undefined : Number(raw))
  const current = value ?? {}

  return (
    <Chip
      field={field}
      summary={rangeSummary(value, unit)}
      onClear={() => onChange(null)}
      trigger={(button) => (
        <Popover>
          <PopoverTrigger asChild>{button}</PopoverTrigger>
          <PopoverContent align="start" className="flex w-64 flex-col gap-3">
            <div className="flex flex-col gap-1">
              {presets.map((preset) => {
                const label = rangeSummary(preset, unit)!
                const on =
                  preset.min === value?.min && preset.max === value?.max
                return (
                  <Button
                    className="justify-start"
                    key={label}
                    onClick={() => set(preset)}
                    size="sm"
                    variant={on ? "secondary" : "ghost"}
                  >
                    {label}
                  </Button>
                )
              })}
            </div>
            <Separator />
            <div className="grid grid-cols-2 gap-2">
              {(["min", "max"] as const).map((bound) => (
                <Field key={bound}>
                  <FieldLabel htmlFor={`${id}-${bound}`}>
                    {bound === "min" ? "Min" : "Max"}
                  </FieldLabel>
                  <InputGroup>
                    <InputGroupInput
                      id={`${id}-${bound}`}
                      inputMode="numeric"
                      onChange={(event) =>
                        set({ ...current, [bound]: read(event.target.value) })
                      }
                      value={current[bound] ?? ""}
                    />
                    <InputGroupAddon align="inline-end">
                      <InputGroupText>{unit}</InputGroupText>
                    </InputGroupAddon>
                  </InputGroup>
                </Field>
              ))}
            </div>
          </PopoverContent>
        </Popover>
      )}
    />
  )
}

/**
 * A filter that is either on or off — "Scheduled only". Clicking the chip
 * turns it on; there is nothing to choose, so nothing opens.
 */
export function ToggleFilter({
  field,
  value,
  onChange,
}: {
  field: string
  value: boolean
  onChange: (value: boolean) => void
}) {
  return (
    <ButtonGroup>
      <Button onClick={() => onChange(!value)} size="xs" variant="outline">
        {value ? (
          <span className="font-semibold">{field}</span>
        ) : (
          <>
            <AddIcon />
            {field}
          </>
        )}
      </Button>
      {value ? (
        <Button
          aria-label={`Clear ${field}`}
          onClick={() => onChange(false)}
          size="icon-xs"
          variant="outline"
        >
          <ClearIcon />
        </Button>
      ) : null}
    </ButtonGroup>
  )
}

/** The filters not shown as chips. Choosing one adds its chip to the row. */
export function AddFilter({
  fields,
  onAdd,
}: {
  fields: { id: string; label: string }[]
  onAdd: (id: string) => void
}) {
  if (!fields.length) return null

  return (
    <DropdownMenu modal={false}>
      <DropdownMenuTrigger asChild>
        <Button variant="ghost" size="xs">
          <AddIcon />
          Filter
        </Button>
      </DropdownMenuTrigger>
      <DropdownMenuContent align="start">
        {fields.map((field) => (
          <DropdownMenuItem key={field.id} onSelect={() => onAdd(field.id)}>
            {field.label}
          </DropdownMenuItem>
        ))}
      </DropdownMenuContent>
    </DropdownMenu>
  )
}

"use client"

import * as React from "react"

import { Item } from "@/components/ui/item"

/**
 * The top of a page, one shape everywhere.
 *
 * Title on the left, with one line of description under it only when the
 * title does not say enough on its own. Whatever describes the page's state —
 * a quota, a sync status — sits on the right, level with the title. The ways
 * of adding to the page come after, as a row of tiles directly under the
 * title, so the reader meets the actions before the list they fill.
 *
 * The layout follows ElevenLabs' knowledge base page; the look is ours.
 */
export function PageHeader({
  title,
  description,
  aside,
  actions,
}: {
  title: React.ReactNode
  /** Optional. Leave it out when the title already says what the page is. */
  description?: React.ReactNode
  /** Page state, shown on the right of the title — never an action. */
  aside?: React.ReactNode
  /** `ActionTile`s. A page with nothing to add has none. */
  actions?: React.ReactNode
}) {
  return (
    <header className="flex flex-col gap-6">
      <div className="flex flex-wrap items-start justify-between gap-4">
        <div className="flex flex-col gap-1">
          <h1 className="text-2xl font-semibold">{title}</h1>
          {description ? (
            <p className="text-sm text-muted-foreground">{description}</p>
          ) : null}
        </div>
        {aside}
      </div>

      {actions ? <div className="flex flex-wrap gap-3">{actions}</div> : null}
    </header>
  )
}

/**
 * One way of adding to the page: an icon over a label, nothing else. The
 * label carries the verb, so there is no second line explaining it — what a
 * choice accepts is said in the dialog it opens.
 */
export function ActionTile({
  icon,
  label,
  onClick,
}: {
  icon: React.ReactNode
  label: string
  onClick?: () => void
}) {
  return (
    <Item
      variant="outline"
      asChild
      /* On the Item, not the button: Slot joins the two class lists without
         merging them, so the Item's own w-full and padding would win. */
      className="w-36 flex-col items-start gap-2 p-3 [&_svg]:size-4 text-start transition-colors duration-150 ease-out-cubic hover:bg-muted motion-reduce:transition-none"
    >
      <button type="button" onClick={onClick}>
        {icon}
        <span className="font-medium">{label}</span>
      </button>
    </Item>
  )
}

